btn = lambda t, k='sec': f'<button style="height: 26px; padding: 0 12px; border-radius: 4px; white-space: nowrap; font-size: 12px; {"background: #246bcb; color: #fff; font-weight: 500;" if k == "pri" else ("color: #a8a8a8;" if k == "ghost" else ("box-shadow: inset 0 0 0 1px #454545; color: #ff938c;" if k == "danger" else "box-shadow: inset 0 0 0 1px #454545;"))}">{t}</button>'
