sm = lambda t, c='#939393': f'<span style="font-size: 11px; line-height: 15px; color: {c}">{t}</span>'
frame = lambda inner, h: f'<div style="position: relative; width: 880px; height: {h}px; display: flex; border-radius: 6px; overflow: hidden; background: #2a2a2a; box-shadow: 0 0 0 1px #303030; font-size: 12px; line-height: 16px">{inner}</div>'
props = lambda title, sub, body, w=300: f'<div style="width: {w}px; flex: none; display: flex; flex-direction: column; border-left: 1px solid #303030; background: #1f1f1f"><div style="padding: 10px 12px; border-bottom: 1px solid #303030"><div style="font-weight: 500">{title}</div><div style="font-size: 11px; color: #939393; margin-top: 3px">{sub}</div></div><div style="padding: 10px 12px; display: flex; flex-direction: column; gap: 8px">{body}</div></div>'
canvas = lambda inner, extra='': f'<div style="position: relative; flex: 1; min-width: 0; {extra}">{inner}</div>'
paper = lambda inner, l=24, t=24, r=24, b=24: f'<div style="position: absolute; left: {l}px; top: {t}px; right: {r}px; bottom: {b}px; overflow: hidden; background: #f6f1ea; color: #1d1a16; font-family: Inter, sans-serif">{inner}</div>'
tag = lambda t, bg='#246bcb', c='#fff': f'<span style="position: absolute; left: -2px; bottom: calc(100% + 3px); height: 18px; padding: 0 6px; display: flex; align-items: center; gap: 4px; background: {bg}; color: {c}; font-size: 10px; font-weight: 500; white-space: nowrap; border-radius: 2px">{t}</span>'
chip = lambda t: f'<span style="height: 22px; display: inline-flex; align-items: center; gap: 6px; padding: 0 9px; border-radius: 11px; background: rgba(47,128,237,0.14); color: #a9c8f7; font-size: 11px; font-weight: 500; white-space: nowrap">{t}</span>'
def sheet(code, title, sub, cells, fname, H):
    body = sheet_header(code, title, sub)
    body += '<div style="display: grid; grid-template-columns: repeat(2, 880px); gap: 48px 32px; align-items: start">' + ''.join(f'<div>{cap(t, d)}{c}</div>' for t, d, c in cells) + '</div>'
    open('/home/claude/daisy/project/' + fname, 'w', encoding='utf-8').write(page(f'Daisy · {code} {title}', 1920, H, body))

