# ═════ D-58b Components · states ═════
k1 = frame(canvas(f'''<div style="position: absolute; left: 24px; top: 20px; width: 520px; padding: 14px; display: flex; flex-direction: column; gap: 10px; {POP}">
<div style="display: flex; align-items: center; gap: 8px">{icon("comp", 15, "#a9c8f7", 1.3)}<b style="font-weight: 600">Make a component from Card 1</b></div>
{row2("Name", fld("Product card", True))}
<span style="font-size: 11px; color: #a8a8a8">Parts that can change per use</span>
{chk(True, "Image · becomes an option (image)")}{chk(True, "“Tide bowl” · becomes an option (text)")}{chk(True, "“€38” · becomes an option (text)")}{chk(False, "Corner radius · keep the same everywhere")}
<div style="display: flex; align-items: center; gap: 8px"><span style="font-size: 11px; color: #939393">Card 2 and Card 3 look the same · they will use it too</span><span style="flex: 1"></span>{btn("Cancel", "ghost")}{btn("Make component", "pri")}</div></div>
<div style="position: absolute; right: 20px; top: 20px; width: 270px; font-size: 11px; line-height: 16px; color: #a8a8a8">Right-click › Make component (Ctrl Alt M). For a header or footer used on many pages use Make shared (Ctrl Alt K). Daisy suggests options from the text and images inside, and finds look-alikes.</div>''', 'background: #1f1f1f;'), 300)
k2 = frame(canvas(paper(f'<div style="padding: 24px"><div style="position: relative; width: 200px; padding: 10px; box-sizing: border-box; border-radius: 8px; background: #fff; outline: 1.5px solid #2f80ed; outline-offset: 2px">{tag(icon("comp", 10, "#fff", 1.5) + "Product card · 2 changes here")}<div style="height: 90px; border-radius: 5px; background: #cfb9a3"></div><div style="margin-top: 8px; font: 15px Fraunces, serif">Ember mug</div><div style="font-size: 12px; color: #b5532d; font-weight: 600">€22 <span style="font-weight: 400; color: #8a8174; text-decoration: line-through">€26</span></div></div></div>', 24, 24, 330, 24))
           + props('Product card', 'Changes on this use · 2', ''.join(f'<div style="height: 26px; display: flex; align-items: center; gap: 6px; padding: 0 8px; border-radius: 3px; background: #2a2a2a; font-size: 11px"><span style="width: 6px; height: 6px; border-radius: 3px; background: #2f80ed"></span><span style="flex: 1">{a}</span><button style="font-size: 11px; color: #a8a8a8">Reset</button></div>' for a in ['Price colour · brand', 'Old price shown']) + '<div style="display: flex; gap: 6px">' + btn('Make this a variant…') + btn('Reset all', 'ghost') + '</div>' + sm('Make this a variant turns these changes into a new variant, e.g. “On sale”.')), 260)
var = lambda n, active, diff=False: f'<div style="display: flex; flex-direction: column; gap: 6px"><span style="font-size: 11px; color: {"#1f5fb5" if active else "#4a443c"}; font-weight: {600 if active else 500}">{n}</span><div style="position: relative; width: 140px; padding: 8px; box-sizing: border-box; border-radius: 8px; background: #fff; {"outline: 1.5px solid #2f80ed; outline-offset: 3px;" if active else ""}"><div style="height: 70px; border-radius: 5px; background: #d8cbb8; {"filter: grayscale(0.7); opacity: 0.55;" if diff else ""}"></div>{"<span style=\"position: absolute; left: 14px; top: 14px; padding: 2px 7px; border-radius: 999px; background: #1d1a16; color: #f6f1ea; font-size: 9px; outline: 1.5px dashed #2f80ed; outline-offset: 2px\">Sold out</span>" if diff else ""}<div style="margin-top: 6px; font: 12px Fraunces, serif; color: #1d1a16">{{name}}</div><div style="font-size: 10px; color: #5f6b4e; {"text-decoration: line-through; color: #8a8174;" if diff else ""}">{{price}}</div></div></div>'
k3 = frame(canvas(f'<div style="position: absolute; left: 24px; top: 10px">{chip(icon("comp", 11, "#a9c8f7", 1.3) + "Product card · component tab · editing Sold out")}</div><div style="position: absolute; left: 24px; top: 46px; display: flex; gap: 18px; padding: 14px; border-radius: 6px; background: #e7d9c7">{var("Default", False)}{var("Sold out", True, True)}{var("Featured", False)}</div>')
           + props('Sold out', 'Variant · differs from Default in 3 places', ''.join(f'<div style="height: 24px; display: flex; align-items: center; gap: 6px; font-size: 11px"><span style="width: 6px; height: 6px; border-radius: 3px; background: #2f80ed"></span><span style="flex: 1">{a}</span><span style="color: #939393">{b}</span></div>' for a, b in [('Badge', 'shown · “Sold out”'), ('Photo', 'greyed 55%'), ('Price', 'struck through')]) + sm('Everything else follows Default. Changing Default updates all variants where they match.')), 280)
k4 = frame(canvas(paper('<div style="padding: 24px; display: flex; gap: 16px"><div style="width: 160px; padding: 8px; border-radius: 8px; background: #fff"><div style="height: 80px; border-radius: 5px; background: #d8cbb8"></div><div style="margin-top: 6px; font: 13px Fraunces, serif">Tide bowl</div></div></div>', 24, 24, 330, 24))
           + props('Product card', 'Swap for another component', f'<div style="display: flex; flex-direction: column; gap: 3px">' + ''.join(f'<div style="height: 30px; display: flex; align-items: center; gap: 8px; padding: 0 8px; border-radius: 3px; {"background: rgba(47,128,237,0.18);" if i == 1 else "background: #2a2a2a;"}">{icon("comp", 12, "#a9c8f7" if i == 1 else "#a8a8a8", 1.3)}<span style="flex: 1">{n}</span><span style="font-size: 10px; color: #939393">{d}</span></div>' for i, (n, d) in enumerate([('Product card', 'current'), ('Product row', 'keeps image, name, price'), ('Journal card', 'keeps image, name')])) + '</div>'
                   + sm('Content moves over where the option names match; anything that does not fit is listed before you swap.') + '<div style="display: flex; gap: 6px">' + btn('Swap this one') + btn('Swap all 9', 'ghost') + '</div>'), 260)
k5 = frame(canvas(f'''<div style="position: absolute; left: 24px; top: 20px; width: 480px; padding: 14px; display: flex; flex-direction: column; gap: 10px; {POP}">
<b style="font-size: 14px; font-weight: 600">Delete Product card?</b><span style="font-size: 12px; line-height: 18px; color: #c8c8c8">It is used <b style="font-weight: 600">9 times</b> on Home and Shop.</span>
<div style="display: flex; flex-direction: column; gap: 6px">{''.join(f'<div style="display: flex; gap: 10px; padding: 9px 10px; border-radius: 5px; {"background: rgba(47,128,237,0.14); box-shadow: inset 0 0 0 1px #2f80ed;" if on else "background: #2a2a2a;"}"><span style="width: 14px; height: 14px; flex: none; box-sizing: border-box; border-radius: 7px; {"border: 4px solid #2f80ed;" if on else "border: 1.5px solid #6b6b6b;"}"></span><span style="display: flex; flex-direction: column; gap: 2px"><span style="font-weight: 500">{t}</span><span style="font-size: 11px; color: #a8a8a8">{d}</span></span></div>' for t, d, on in [("Keep the uses as plain copies", "They look the same and can be edited one by one", True), ("Replace them with another component", "Product row ▾", False)])}</div>
<div style="display: flex; gap: 8px">{btn("Cancel", "ghost")}<span style="flex: 1"></span>{btn("Delete component", "danger")}</div></div>
<div style="position: absolute; right: 20px; top: 20px; width: 290px; font-size: 11px; line-height: 16px; color: #a8a8a8"><b style="color: #e8e8e8">Detach one use</b> works the same way for a single card: it becomes a plain copy, and the component and the other uses are untouched. Undo brings it back.</div>''', 'background: #1f1f1f;'), 280)
sheet('D-58b', 'Components · states', 'Making a component, changes on one use, editing a variant, swapping, and deleting or detaching. Read with D-58.',
      [('1 · Making a component', 'Suggests which parts become options and finds look-alikes to link.', k1), ('2 · Changes on one use', 'Listed with reset; can become a new variant.', k2),
       ('3 · Editing a variant', 'In the component tab; shows exactly where it differs from Default.', k3), ('4 · Swapping', 'Replace with another component; matching content moves over.', k4),
       ('5 · Deleting or detaching', 'Uses become plain copies or another component; nothing disappears from pages.', k5)],
      'D58b-Components-States.dc.html', 1340)
print('ok')
